using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Enums; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class ContactRepository(ProjetoIntegradorBackDbContext context):IContactRepository{
public async Task<Result<Contact>> AddAsync(Contact e,CancellationToken ct=default){try{e.Id=Guid.NewGuid();e.CreatedAt=DateTime.UtcNow;await context.Contacts.AddAsync(e,ct);await context.SaveChangesAsync(ct);return Result<Contact>.AsSuccess(e);}catch(Exception ex){return Result<Contact>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<IReadOnlyList<Contact>>> ListAsync(StatusContact? status,int page,int size,CancellationToken ct=default){try{var q=context.Contacts.AsQueryable();if(status.HasValue)q=q.Where(x=>x.Status==status);return Result<IReadOnlyList<Contact>>.AsSuccess(await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*size).Take(size).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Contact>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<int>> ContarAsync(StatusContact? status,CancellationToken ct=default){try{var q=context.Contacts.AsQueryable();if(status.HasValue)q=q.Where(x=>x.Status==status);return Result<int>.AsSuccess(await q.CountAsync(ct));}catch(Exception ex){return Result<int>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Contact>> UpdateStatusAsync(Guid id,StatusContact status,CancellationToken ct=default){try{var e=await context.Contacts.FindAsync(new object[]{id},ct);if(e==null)return Result<Contact>.AsFailure(new Failure(404,"Contact não encontrado."));e.Status=status;await context.SaveChangesAsync(ct);return Result<Contact>.AsSuccess(e);}catch(Exception ex){return Result<Contact>.AsFailure(new Failure(500,ex.Message));}}}